import base64

def convert_base64_to_html(base64_string, output_file_path):
    try:
        # Giải mã Base64 thành bytes
        html_content = base64.b64decode(base64_string)

        # Ghi nội dung HTML vào file
        with open(output_file_path, 'wb') as file:
            file.write(html_content)

        print(f"HTML file has been successfully restored at: {output_file_path}")
    except Exception as e:
        print(f"Error decoding Base64: {e}")

# Base64 chuỗi đầu vào (thay thế bằng chuỗi thật của bạn)
base64_string = ""  

# Đường dẫn lưu file HTML sau khi giải mã
output_html_path = 'assets/html/output.html'

if __name__ == "__main__":
    convert_base64_to_html(base64_string, output_html_path)
